public class Dispatch {
    static class Animal {
        String name = "animal-field";
        String sound() { return "..."; }
        String greet(Animal other) { return "Animal meets Animal"; }
    }
    static class Dog extends Animal {
        String name = "dog-field";
        @Override String sound() { return "Woof"; }
        String greet(Dog other) { return "Dog meets Dog"; }   // overload, NOT an override
    }

    public static void main(String[] args) {
        Animal a = new Dog();
        System.out.println(a.sound());         // dynamic: Woof
        System.out.println(a.name);            // fields use the static type
        System.out.println(((Dog) a).name);    // cast changes the static type
        Dog d = new Dog();
        System.out.println(d.greet(d));        // Dog meets Dog
        System.out.println(a.greet(d));        // overload chosen by static type of a
        Animal plain = new Animal();
        try { Dog bad = (Dog) plain; }
        catch (ClassCastException e) {
            System.out.println("CCE: " + e.getMessage().substring(0, 60));
        }
        Object o = d;
        if (o instanceof Dog dd && dd.name.startsWith("dog")) {
            System.out.println("pattern ok: " + dd.sound());
        }
        System.out.println(null instanceof Animal);
    }
