public class Shapes {
    interface Drawable {
        void draw();
        default String label() { return "Drawable:" + name(); }
        private String name() { return getClass().getSimpleName(); }
        static Drawable of(String text) { return () -> System.out.println("text " + text); }
    }

    static abstract class Shape implements Drawable {
        private final String color;
        Shape(String color) { this.color = color; }       // constructors are allowed
        abstract double area();                           // subclasses must supply this
        public void draw() {
            System.out.println(color + " " + getClass().getSimpleName()
                    + " area=" + String.format("%.2f", area()));
        }
    }
    static class Circle extends Shape {
        private final double r;
        Circle(String c, double r) { super(c); this.r = r; }
        double area() { return Math.PI * r * r; }
    }
    static class Rect extends Shape {
        private final double w, h;
        Rect(String c, double w, double h) { super(c); this.w = w; this.h = h; }
        double area() { return w * h; }
    }

    public static void main(String[] args) {
        Shape[] shapes = { new Circle("red", 1.5), new Rect("blue", 2, 3) };
        for (Shape s : shapes) {
            s.draw();
            System.out.println(s.label());
        }
        Drawable.of("hello").draw();
        // new Shape("x");   // compile error: Shape is abstract; cannot be instantiated
