public class Boxing {
    public static void main(String[] args) {
        Integer a = 127, b = 127;
        Integer c = 128, d = 128;
        System.out.println("127 == 127 : " + (a == b));
        System.out.println("128 == 128 : " + (c == d));
        System.out.println("128 equals : " + c.equals(d));
        Integer e = Integer.valueOf(1000), f = Integer.valueOf(1000);
        System.out.println("valueOf(1000) == : " + (e == f));
        System.out.println("Long 127 == : " + (Long.valueOf(127) == Long.valueOf(127)));
        System.out.println("Long 128 == : " + (Long.valueOf(128) == Long.valueOf(128)));
        System.out.println("Character 'a' == : "
            + (Character.valueOf('a') == Character.valueOf('a')));
        System.out.println("Boolean == : " + (Boolean.valueOf(true) == Boolean.valueOf("TRUE")));
        System.out.println("Double 1.0 == : " + (Double.valueOf(1.0) == Double.valueOf(1.0)));
        System.out.println("Integer vs Long equals : "
            + Integer.valueOf(5).equals(Long.valueOf(5)));
        System.out.println("Integer == int : " + (c == 128));

        List<Integer> list = new ArrayList<>(List.of(10, 20, 30, 1));
        list.remove(1);
        System.out.println("after remove(1)            : " + list);
        list.remove(Integer.valueOf(1));
        System.out.println("after remove(Integer 1)    : " + list);

        Map<String, Integer> stock = new HashMap<>();
        stock.put("pen", 5);
        try {
            int n = stock.get("ink");
            System.out.println(n);
        } catch (NullPointerException ex) {
            System.out.println("NPE unboxing a missing map value");
        }
        boolean flag = false;
        try {
            Integer r = flag ? 1 : (Integer) null;
            System.out.println(r);
        } catch (NullPointerException ex) {
            System.out.println("NPE from ternary with int operand");
        }
        Integer ok = flag ? Integer.valueOf(1) : null;
        System.out.println("both boxed: " + ok);

        Integer x = 10;
        Integer y = x;
        x++;
        System.out.println("x=" + x + " y=" + y);

        Object o = true ? Integer.valueOf(1) : Double.valueOf(2.0);
        System.out.println("mixed ternary: " + o);
    }
}

