import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.concurrent.atomic.AtomicInteger;

public class Nums {
    public static void main(String[] args) {
        Class<?>[] types = {Integer.class, Double.class, BigDecimal.class, BigInteger.class,
            AtomicInteger.class, Character.class, Boolean.class};
        for (Class<?> t : types) {
            System.out.println(t.getSimpleName() + " extends " + t.getSuperclass().getSimpleName()
                + ", Number? " + Number.class.isAssignableFrom(t));
        }
        Number n = 3.99;
        System.out.println(n.intValue() + " " + n.longValue() + " " + n.doubleValue());
        System.out.println(Integer.parseInt("42") + 1);
        System.out.println(Integer.valueOf("42") + 1);
        System.out.println(Integer.toBinaryString(42) + " " + Integer.toHexString(255)
            + " " + Integer.parseInt("ff", 16));
        System.out.println(Integer.compare(3, 7) + " " + Integer.signum(-9)
            + " " + Integer.sum(2, 3) + " " + Integer.MAX_VALUE + " " + Integer.BYTES);
        try { Integer.parseInt("12x"); } catch (NumberFormatException e) {
            System.out.println(e.getMessage());
        }
        System.out.println(Double.compare(0.0, -0.0) + " " + (0.0 == -0.0)
            + " " + Double.valueOf(0.0).equals(-0.0));
        System.out.println(Double.valueOf(Double.NaN).equals(Double.NaN)
            + " " + (Double.NaN == Double.NaN));
    }
}
